import "./Hello.css";

export default function Hello() {
    function showName() {
        console.log("Mike");
    }
    function showAge(age) {
        console.log(age);
    }
    return (
        <div className = "helloBox">
        <h1>Hello</h1>
        <button onClick = {showName()}>Show name</button>
        <button>Show age</button>
        </div>
    );
}
